"""The further-reading list for Modern Enterprise Architecture v2: Architecting for humans, in deck order.
Each entry: citation, slides (headlines), what it says, caveat, links.
Link kinds: free (open-access copy), web (free web page or video), borrow (archive.org lending),
paywall (publisher or subscription), buy (a shop)."""
def amazon(q):
    from urllib.parse import quote_plus
    return ("buy", "amazon.de", "https://www.amazon.de/s?k=" + quote_plus(q) + "&i=stripbooks")

def shop(url, label):
    return ("buy", label, url)

def ia(ident, label="Borrow free (archive.org)"):
    return ("borrow", label, "https://archive.org/details/" + ident)

def doi(d, label="Publisher (paywalled)"):
    return ("paywall", label, "https://doi.org/" + d)

def paid(url, label):
    return ("paywall", label, url)

def free(url, label="Free PDF"):
    return ("free", label, url)

def web(url, label="Website"):
    return ("web", label, url)

def yt(vid, label="Watch (YouTube)", t=None):
    return ("web", label, "https://www.youtube.com/watch?v=" + vid + (f"&t={t}s" if t else ""))

